from html.parser import HTMLParser
from pathlib import Path
import hashlib, json, re

class ListingText(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hidden = None
        self.chunks = []

    def handle_starttag(self, tag, attrs):
        if tag in {'script', 'style', 'noscript', 'template'}:
            self.hidden = tag

    def handle_endtag(self, tag):
        if tag == self.hidden:
            self.hidden = None

    def handle_data(self, data):
        if self.hidden is None:
            self.chunks.append(' '.join(data.split()))

source = Path('products/distribution/sqlite-paid-education-shelf/raw/high-performance-sqlite.html')
raw = source.read_bytes()
digest = hashlib.sha256(raw).hexdigest()
assert digest == '580195c1f328d0357cbbe5adea69a0bf1c28009fd89d17dc539dd36df9ca09b3'
page = ListingText()
page.feed(raw.decode('utf-8'))
lines = [line for line in page.chunks if line]
patterns = {'price': r'\$\s*\d|\b(?:USD|CAD)\b', 'sample': r'\b(?:preview|sample|free lesson|watch for free)\b', 'scope': r'High Performance SQLite|\b(?:lessons|modules|curriculum|hours of)\b'}
excerpts = {}
for label, pattern in patterns.items():
    matches = [i for i, line in enumerate(lines) if re.search(pattern, line, re.I)]
    excerpts[label] = [{'text': lines[i][:400], 'nearby': lines[max(0, i-2):i+3]} for i in matches[:8]]
report = {'source': 'https://databaseschool.com/?banner=sqlite', 'capture_receipt': 'TASK-179578440101', 'sha256': digest, 'excerpts': excerpts, 'scope': 'Static HTML text excerpts for manual listing comparison. Confirm that each price and scope excerpt refers to this SQLite product. No sales or enrollment inference.'}
out = Path('products/distribution/sqlite-paid-education-shelf/director-original-listing-excerpts.json')
out.write_text(json.dumps(report, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
print(json.dumps({key: len(items) for key, items in excerpts.items()}))
